-- Kitap kütüphanesi genişlemesi (19 Eylül 2026): 28 → 81 kitap, seviye
-- işaretleri, 18 yeni söz. Sayfa sayıları yaygın Türkçe baskılara göre
-- yaklaşık; süre sayfa × 1,15 dk.

update public.haftalik_kitap set seviye = 'yks' where ad in (
  '1984', 'Sineklerin Tanrısı', 'Bir İdam Mahkûmunun Son Günü', 'İvan İlyiç''in Ölümü',
  'Yeraltından Notlar', 'Anayurt Oteli', 'Bir Bilim Adamının Romanı', 'Denemeler',
  'Bilinmeyen Bir Kadının Mektubu', 'Fareler ve İnsanlar', 'Yaban', 'Sokrates''in Savunması');


